mapper.select:
SELECT al.annual_leave_code, al.company_code, al.user_id, um.user_name, dm.dept_name, FN_FIND_CODENAME('0C',job_title) as job_title, al.grant_year, al.total_grant_days, al.total_used_days, al.remaining_days, al.expiry_date FROM tb_annual_leave al JOIN tb_user_master um ON um.user_id = al.user_id JOIN tb_dept_master dm ON dm.dept_code = um.dept WHERE al.company_code = #{companyCode} AND um.leave_date IS NULL
AND um.user_name like '%' || #{userName} || '%'
AND dm.dept_code = #{deptCode}
AND al.remaining_days >= #{remainingDaysStart}
AND al.remaining_days <= #{remainingDaysEnd}
ORDER BY TO_NUMBER(grant_year) DESC, al.user_id
